drop table soe.cust_info purge;
create table soe.cust_info (
CUST_ID  NUMBER                   ,
CUST_NM           VARCHAR2(100)   ,
JUMIN_NO          VARCHAR2(100)   ,
GENDER            VARCHAR2(10)    ,
AGE               NUMBER          ,
EDU               VARCHAR2(100)   ,
JOB               VARCHAR2(100)   ,
child             number          ,
created           varchar2(8)     ,
EMAIL             VARCHAR2(200)   ,
HP_NO             VARCHAR2(100)   ,
GUNMUL            VARCHAR2(200)   ,
JUNGDONG          VARCHAR2(200)   ,
JUSO              VARCHAR2(200)   ,
LAT               NUMBER          ,
LON               NUMBER          )
;

alter table soe.cust_info add constraint cust_info_pk primary key (cust_id);



